/**
 * The demo bundle, generated by `scripts/build-web-data.sh`.
 *
 * `docs/09`: "Every displayed number comes from a retained fixture or an
 * actual transaction-derived record." Loading a static bundle enforces
 * that structurally -- the demo produced the file, or the screen has
 * nothing to render. There is no code path where the interface computes a
 * figure the engine never returned.
 */

export interface Assessment {
  assessment_id: string;
  binding_key: string;
  input_hash: string;
  model_hash: string;
  policy_hash: string;
  assessment_kind: string;
  decision: string;
  risk_permission: string | null;
  sequence: number;
  assessment_hash: string;
  created_at: number;
  /** The full canonical assessment the engine returned. */
  payload: AssessmentPayload;
}

export interface AssessmentPayload {
  assessment_id: string;
  assessment_time: number;
  authorization_class: string;
  input_hash: string;
  model_hash: string;
  policy_hash: string;
  schema_version: string;
  sequence: number;
  /**
   * Engine reasons: a unit variant is a string, a variant carrying data
   * is a single-key object. Typed as `string[]` until 15 September, which
   * rendered every structured reason as `[object Object]`.
   */
  reasons: Reason[];
  omitted_evidence: string[];
  synthetic_used?: boolean;
  outcome: Outcome;
  stress_results?: StressResult[];
}

export interface Outcome {
  decision: string;
  requested_principal?: string;
  approved_principal?: string;
  capacity?: Capacity;
  terms?: Terms;
}

export interface Capacity {
  agent_capacity: string;
  agent_binding: string;
  drawable_capacity: string;
  drawable_binding: string;
  score: number | null;
}

export interface Terms {
  approved_principal: string;
  apr_bps: number;
  term_seconds: number;
  required_equity: string;
  price_breakdown?: PriceBreakdown;
  economics?: Record<string, string | number>;
}

export interface PriceBreakdown {
  apr_bps: number;
  base_rate_bps: number;
  clamped: boolean;
  history_discount_bps: number;
  portfolio_surcharge_bps: number;
}

export interface StressResult {
  applied_price_shock_bps?: number;
  [k: string]: unknown;
}

/** One check `credence-verify` ran against the live deployment. */
export interface Check {
  beat: string;
  name: string;
  passed: boolean;
  /** Verbatim, because it holds the revert selector. */
  detail: string;
}

/** A probability committed BEFORE the loan was funded (`docs/06`). */
export interface Forecast {
  forecast_id: string;
  binding_key: string;
  committed_at: number;
  event_definition: string;
  horizon_seconds: number;
  probability_ppm: number;
  payload?: Record<string, unknown>;
}

/** How a forecast actually resolved. */
export interface ForecastOutcome {
  forecast_id: string;
  outcome_id: string;
  resolution: string;
  resolved_at: number;
  brier_ppm: number;
}

import type { Reason } from "./reasons";

/** One evidence item as the engine received it (`docs/04`). */
export interface Evidence {
  evidence_id: string;
  source: string;
  origin: string;
  requirement: string;
  state: string;
  coverage: string;
  observed_at: number;
  retrieved_at: number;
  content_hash: string;
  scenario_id: string | null;
  value?: unknown;
}

/** The snapshot the engine hashed, item by item. */
export interface Snapshot {
  assessment_time: number;
  account?: Evidence;
  market?: Evidence;
  history?: Evidence;
  forecasts?: Evidence;
  portfolio?: Evidence;
  [k: string]: unknown;
}

export interface Run {
  name: string;
  /** Present when the run recorded on-chain checks. */
  checks?: Check[];
  assessments: Assessment[];
  /** Keyed by input_hash, so an assessment pairs with its exact snapshot. */
  snapshots: Record<string, Snapshot>;
  outcomes: ForecastOutcome[];
  forecasts: Forecast[];
  chain_events: unknown[];
}

export interface Manifest {
  runs: { name: string; assessments: number; snapshots: number }[];
  generated_from: string[];
  deployment?: Record<string, unknown>;
}

/** One agent profile in `docs/09` beat 1's comparison. */
export interface Profile {
  name: string;
  blurb: string;
  assessment: AssessmentPayload;
}

export interface Comparison {
  policy_hash: string;
  model_hash: string;
  profiles: Profile[];
}

const cache = new Map<string, unknown>();

async function fetchJSON<T>(path: string): Promise<T> {
  const hit = cache.get(path);
  if (hit) return hit as T;
  const res = await fetch(path);
  if (!res.ok) {
    // A missing bundle is a missing demo run, not an empty one. Say which,
    // because the fix is to run the script rather than to debug the page.
    throw new Error(
      `${path} is not available (${res.status}). ` +
        `Generate the bundle with: pnpm data`,
    );
  }
  const body = (await res.json()) as T;
  cache.set(path, body);
  return body;
}

export const loadManifest = () => fetchJSON<Manifest>("data/manifest.json");
export const loadRun = (name: string) => fetchJSON<Run>(`data/${name}.json`);
/**
 * The policy a given run actually hashed.
 *
 * Per run, not one shared file. `demo-monitor.sh` runs on a gateway
 * template whose `base_history_cap` is 10e9 while the shipped policy is
 * 6.2e9, and the engine refuses a declared policy hash that is not the
 * content hash of the policy it was handed. Loading the wrong one made a
 * CLEAN replay return `Unavailable` -- a DIFFERENCE, which would have made
 * the replay screen prove the opposite of what it claims.
 */
export const loadComparison = () =>
  fetchJSON<Comparison>("data/comparison.json");

export const loadPolicy = (run: string) =>
  fetchJSON<unknown>(`data/${run}-policy.json`);

/** Base units to a readable decimal. Never rounds a displayed amount. */
export function units(raw: string | number | undefined, decimals = 6): string {
  if (raw === undefined) return "-";
  const s = String(raw);
  if (!/^\d+$/.test(s)) return s;
  const pad = s.padStart(decimals + 1, "0");
  const whole = pad.slice(0, pad.length - decimals);
  const frac = pad.slice(pad.length - decimals).replace(/0+$/, "");
  return frac ? `${Number(whole).toLocaleString()}.${frac}` : Number(whole).toLocaleString();
}

export const bps = (v: number | undefined): string =>
  v === undefined ? "-" : `${(v / 100).toFixed(2)}%`;
